"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[2572],{7654(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Chapter 3: Modern Smartphone Photography","description":"A tour of the computational and optical features on modern phones: HDR, portrait bokeh, night mode, slow-motion, ultra-wide, telephoto, macro, and how computational photography fuses hardware and software.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/camera2/what-can-modern-smartphone-cameras-do.md","sourceDirName":"camera2","slug":"/camera2/what-can-modern-smartphone-cameras-do","permalink":"/AndroidCameraParameters/fr/camera2/what-can-modern-smartphone-cameras-do","draft":false,"unlisted":false,"editUrl":"https://github.com/zoozooll/AndroidCameraParameters/tree/main/website/docs/camera2/what-can-modern-smartphone-cameras-do.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Chapter 3: Modern Smartphone Photography","description":"A tour of the computational and optical features on modern phones: HDR, portrait bokeh, night mode, slow-motion, ultra-wide, telephoto, macro, and how computational photography fuses hardware and software.","keywords":["HDR photography","portrait mode","night mode","slow motion video","ultra wide camera","telephoto","computational photography"]},"sidebar":"tutorialSidebar","previous":{"title":"Chapter 2: Understanding Smartphone Cameras","permalink":"/AndroidCameraParameters/fr/camera2/understanding-smartphone-cameras"},"next":{"title":"Chapter 4: Explore Your Own Phone","permalink":"/AndroidCameraParameters/fr/camera2/exploring-your-phones-camera"}}');var o=a(4848),n=a(8453);const i={sidebar_position:3,title:"Chapter 3: Modern Smartphone Photography",description:"A tour of the computational and optical features on modern phones: HDR, portrait bokeh, night mode, slow-motion, ultra-wide, telephoto, macro, and how computational photography fuses hardware and software.",keywords:["HDR photography","portrait mode","night mode","slow motion video","ultra wide camera","telephoto","computational photography"]},s="Chapter 3: Modern Smartphone Photography",l={},h=[{value:"HDR: High Dynamic Range Multi-Frame Fusion",id:"hdr-high-dynamic-range-multi-frame-fusion",level:2},{value:"How Smartphone HDR Works",id:"how-smartphone-hdr-works",level:3},{value:"When HDR Works and When It Doesn&#39;t",id:"when-hdr-works-and-when-it-doesnt",level:3},{value:"Portrait Mode: Bokeh via Depth Estimation",id:"portrait-mode-bokeh-via-depth-estimation",level:2},{value:"Three Methods of Smartphone Depth Estimation",id:"three-methods-of-smartphone-depth-estimation",level:3},{value:"The Portrait Rendering Pipeline",id:"the-portrait-rendering-pipeline",level:3},{value:"Night Mode: Multi-Frame Temporal Merging",id:"night-mode-multi-frame-temporal-merging",level:2},{value:"The Night Mode Algorithm Step-by-Step",id:"the-night-mode-algorithm-step-by-step",level:3},{value:"Slow Motion: High-Frame-Rate Cropped Capture",id:"slow-motion-high-frame-rate-cropped-capture",level:2},{value:"Why 960 fps Requires a Sensor Crop",id:"why-960-fps-requires-a-sensor-crop",level:3},{value:"Ultra-Wide: Distortion Correction and Edge Quality",id:"ultra-wide-distortion-correction-and-edge-quality",level:2},{value:"Telephoto: Standard vs Periscope",id:"telephoto-standard-vs-periscope",level:2},{value:"Macro: Extreme Close-Up Photography",id:"macro-extreme-close-up-photography",level:2},{value:"Computational Photography: The Unifying Philosophy",id:"computational-photography-the-unifying-philosophy",level:2},{value:"Summary",id:"summary",level:2},{value:"What&#39;s Next",id:"whats-next",level:2}];function d(e){const t={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"chapter-3-modern-smartphone-photography",children:"Chapter 3: Modern Smartphone Photography"})}),"\n",(0,o.jsxs)(t.p,{children:["Chapter 2 gave you the hardware foundations: lenses, sensors, ISP pipelines, and multi-camera modules. This chapter answers the natural follow-up question: ",(0,o.jsx)(t.strong,{children:"How do modern camera apps actually use that hardware to produce the photos I see on Instagram?"})]}),"\n",(0,o.jsx)(t.p,{children:"A 2010 smartphone took a single exposure, ran it through a basic ISP, and wrote a JPEG. A 2026 smartphone routinely captures 5 to 15 separate frames for a single still photo, aligns them to sub-pixel precision using gyroscope data, fuses them using multi-frame signal processing, runs the result through a neural network for semantic segmentation or depth estimation, and finally tone-maps it into a single shareable image \u2014 all within the span of a single shutter button press."}),"\n",(0,o.jsx)(t.p,{children:"This chapter is a feature-by-feature tour of modern smartphone photography. We will explain how each feature works at the hardware + software level, without any Camera2 API code. The goal is to build a vocabulary of what modern camera systems can do, so that when you later write code to control these features, you know what is happening under the hood."}),"\n",(0,o.jsx)(t.h2,{id:"hdr-high-dynamic-range-multi-frame-fusion",children:"HDR: High Dynamic Range Multi-Frame Fusion"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Dynamic range"})," is the ratio between the brightest and darkest parts of a scene that the imaging system can record simultaneously without clipping. The human eye can perceive roughly 20 stops of dynamic range (a 1,000,000:1 contrast ratio) in a single glance, thanks to saccadic adaptation. A single smartphone sensor exposure can capture roughly 10 to 12 stops at base ISO. The gap between those two numbers is the reason HDR exists."]}),"\n",(0,o.jsx)(t.p,{children:"Imagine you are taking a photo indoors with a bright window behind your subject. If you expose for the person's face (let's say 1/30s, ISO 400), the window blows out to pure clipped white \u2014 no sky, no clouds, no detail. If you expose for the window (1/2000s, ISO 50), the person's face becomes a silhouetted black blob. Neither single exposure works."}),"\n",(0,o.jsx)(t.h3,{id:"how-smartphone-hdr-works",children:"How Smartphone HDR Works"}),"\n",(0,o.jsxs)(t.p,{children:["Every HDR system on modern phones uses ",(0,o.jsx)(t.strong,{children:"multi-frame bracketing"})," followed by computational fusion. The algorithm works like this:"]}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Bracketed capture"}),": The camera captures a rapid burst of 3 to 10 consecutive frames at different exposure values (EV). A typical set might be frames at -3 EV (very short, preserves highlights), -1 EV, +1 EV, and +3 EV (very long, captures shadows). The sensor and VCM are held perfectly still during the burst; only the electronic shutter timing changes."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Reference frame selection"}),": The algorithm picks the sharpest mid-exposure frame as the geometric reference."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Image registration / alignment"}),": Each non-reference frame is computationally aligned to the reference. The algorithm finds distinctive keypoint features (corners, edges) using algorithms like FAST or SIFT, computes an affine or homography transform that maps each frame's features onto the reference frame, and warps the pixels accordingly. Any frames that are too blurred (from micro-shake during the burst) are discarded entirely."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Fusion"}),": For each pixel location in the final image, the algorithm combines information from the aligned frames. Underexposed pixels contribute their clean, unclipped highlight data. Overexposed pixels contribute their low-noise shadow data. Mid-tone pixels are averaged across all frames to reduce shot noise."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Tone mapping"}),": The fused linear image \u2014 which may now contain 14 to 18 stops of usable dynamic range \u2014 is compressed through a sophisticated local tone mapping operator into an 8-bit or 10-bit output image that looks good on a standard sRGB display."]}),"\n"]}),"\n",(0,o.jsx)(t.mermaid,{value:"flowchart LR\n    A[Scene: Bright Window + Dark Room] --\x3e B[Burst Capture]\n    B --\x3e C1[-3 EV Frame\\nDark, Preserves Highlights]\n    B --\x3e C2[0 EV Frame\\nMid-Exposure Reference]\n    B --\x3e C3[+3 EV Frame\\nBright, Preserves Shadows]\n    C1 --\x3e D[Registration / Alignment\\nFeature Matching + Warp]\n    C2 --\x3e D\n    C3 --\x3e D\n    D --\x3e E[Merge / Fuse\\nPer-Pixel Exposure Blend]\n    E --\x3e F[Local Tone Mapping\\n16 Stops \u2192 8-Bit Displayable]\n    F --\x3e G[Final HDR Output\\nFace Visible + Sky Detailed]"}),"\n",(0,o.jsxs)(t.p,{children:['Real-world example: a Galaxy S26 Ultra in the default "Scene Optimizer HDR" mode internally fires 7 bracketed frames totaling approximately 0.2 seconds of capture time. The built-in hand-motion detection discards 2 blurred frames. The remaining 5 frames are aligned, fused, and tone-mapped. The output is written as a ',(0,o.jsx)(t.strong,{children:"JPEG_R Ultra HDR file"})," on Android 14+ devices: a standard JPEG primary image (8-bit SDR) with an embedded gain map that HDR-capable viewers (Android 14 Gallery, Chrome 120+, Adobe Lightroom) can use to reconstruct the full 10-bit HDR luminance range on an HDR10 or Dolby Vision display."]}),"\n",(0,o.jsx)(t.h3,{id:"when-hdr-works-and-when-it-doesnt",children:"When HDR Works and When It Doesn't"}),"\n",(0,o.jsx)(t.p,{children:'HDR excels at static scenes with both bright highlights and deep shadows: landscapes, backlit portraits, rooms with windows, sunsets over water. It actively fails \u2014 producing ghosting artifacts \u2014 when objects in the scene move during the bracketed burst: a flying bird, a waving flag, a person blinking, a child running. Modern AI-powered HDR algorithms detect and segment moving objects, blending only the reference frame for those pixels to avoid the classic HDR "ghost."'}),"\n",(0,o.jsx)(t.h2,{id:"portrait-mode-bokeh-via-depth-estimation",children:"Portrait Mode: Bokeh via Depth Estimation"}),"\n",(0,o.jsxs)(t.p,{children:["Portrait mode produces the aesthetic where the subject's face is perfectly sharp and the background dissolves into a creamy, out-of-focus blur called ",(0,o.jsx)(t.strong,{children:"bokeh"}),". Traditional cameras achieve this optically with large sensors, wide apertures, and long focal lengths. Smartphones achieve it computationally, because a 1/1.3-inch sensor at f/1.6 does not naturally produce enough shallow depth of field for the effect."]}),"\n",(0,o.jsx)(t.h3,{id:"three-methods-of-smartphone-depth-estimation",children:"Three Methods of Smartphone Depth Estimation"}),"\n",(0,o.jsx)(t.p,{children:"There are three independent techniques used by modern portrait systems; many phones use a combination of all three."}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Method 1: Stereo Disparity from Dual Cameras."})," This is the oldest and most geometrically sound method. The phone fires both the wide camera and the telephoto camera simultaneously at the same subject. Because the two cameras are physically separated by 10 to 15 millimeters (the \"baseline\"), they see the subject from slightly different horizontal positions. A foreground object's position shifts more between the two viewpoints than a distant background object's position does. This shift is called ",(0,o.jsx)(t.strong,{children:"disparity"}),". The algorithm runs a block-matching or semi-global matching (SGM) algorithm over the two rectified images to compute a disparity value for every pixel. Disparity is inversely proportional to depth, so the disparity map is converted directly into a per-pixel depth map."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Method 2: ToF / LiDAR Active Depth Sensing."})," A ToF (Time-of-Flight) or LiDAR depth sensor projects a structured pattern of 30,000+ near-infrared laser dots onto the scene, then measures the round-trip time (for direct ToF) or phase shift (for indirect ToF) of the reflected light to compute a true metric depth in meters for each pixel. ToF produces accurate, dense depth maps even in complete darkness and on textureless surfaces (plain walls, sky) where stereo matching fails. Modern portrait systems typically use ToF as the ground-truth depth cue and stereo disparity as a refinement signal."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Method 3: Monocular ML Depth Estimation."})," For single-camera phones (or for the front-facing selfie camera, which has no stereo partner), a neural network estimates depth from a single RGB image. The model, trained on millions of images with ground-truth depth labels, learns the statistical cues humans use to judge depth: relative size, occlusion, linear perspective, texture gradient, defocus blur, and atmospheric perspective. Google's PortraitNet and Meta's DeepLabV3+ are representative architectures. Monocular depth is less metrically accurate than stereo or ToF, but it is sufficient for plausible-looking portrait bokeh."]}),"\n",(0,o.jsx)(t.h3,{id:"the-portrait-rendering-pipeline",children:"The Portrait Rendering Pipeline"}),"\n",(0,o.jsx)(t.p,{children:"Once a depth map is obtained, the remaining steps are the same regardless of which depth estimation method was used:"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Subject Segmentation"}),': A separate semantic segmentation neural network (usually a U-Net variant) runs on the main RGB camera image and produces a soft alpha mask identifying which pixels belong to "person" vs "background." The mask is feathered at the edges \u2014 especially around hair, glasses, and fine foreground detail \u2014 to avoid the cutout "paper doll" look of early 2010s portrait mode.']}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Depth Refinement"}),": The raw depth map from Method 1/2/3 is multiplied with the segmentation mask. Background pixels keep their depth value; subject pixels are clamped to a single focus plane depth."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Per-Pixel Variable Blur"}),': Each background pixel is blurred by a Gaussian (or, for premium "optical simulation" modes, a physically rendered lens-kernel convolution) whose radius scales linearly with the pixel\'s distance from the focus plane. A background object at 5 meters gets a heavy blur; a background object at 1.5 meters gets a mild blur. The subject pixels are copied untouched.']}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Faux Optical Glare"}),": A premium touch: bright specular highlights in the blurred background (streetlights, reflections, the sun) are rendered as characteristic lens-shaped bokeh hexagons or circles rather than simple Gaussian blobs. This sells the illusion that the blur came from a real lens diaphragm."]}),"\n"]}),"\n",(0,o.jsx)(t.mermaid,{value:"flowchart TD\n    A[Wide Camera Frame + Tele Camera Frame / ToF Data] --\x3e B[Depth Estimation\\nStereo / ToF / Mono ML]\n    B --\x3e C[Depth Map\\n0.5m \u2192 Infinity]\n    A --\x3e D[Subject Segmentation\\nU-Net Neural Network]\n    D --\x3e E[Person Alpha Mask\\nSoft-Edged Feathering]\n    C --\x3e F[Per-Pixel Blur Radius\\nScales with Depth]\n    E --\x3e F\n    F --\x3e G[Apply Variable Blur\\nSubject = Sharp, Background = Bokeh]\n    G --\x3e H[Add Bokeh Speculars\\nHexagonal / Circular Highlights]\n    H --\x3e I[Final Portrait Photo\\nCreamy Background Blur]"}),"\n",(0,o.jsx)(t.h2,{id:"night-mode-multi-frame-temporal-merging",children:"Night Mode: Multi-Frame Temporal Merging"}),"\n",(0,o.jsxs)(t.p,{children:["Before 2018, low-light smartphone photography was essentially unusable without flash. A dimly lit bar or a city street at night produced a noisy, grainy, blurry mess. Then Google released ",(0,o.jsx)(t.strong,{children:"Night Sight"})," on the Pixel 3, and everything changed. The core insight was counterintuitive: instead of taking one long 1-second exposure (which would be hopelessly blurred from hand shake), take 15 very short 1/15-second exposures (each individually sharp because OIS is active), then algorithmically align and average them. The total integrated exposure time is still 1 second, but the per-frame exposure is short enough that handshake blur never accumulates."]}),"\n",(0,o.jsx)(t.h3,{id:"the-night-mode-algorithm-step-by-step",children:"The Night Mode Algorithm Step-by-Step"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Burst Capture"}),": The camera captures 8 to 15 raw frames. Each frame uses a moderate exposure time (1/15s to 1/8s is typical) and moderate ISO (800 to 3200). Individual frames are noisy but not blurred. The burst totals 0.5 to 2 seconds of wall-clock time."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Gyro-Aided EIS Alignment"}),": The phone's main IMU gyroscope records angular velocity at 8,000 Hz throughout the burst. For each frame, the cumulative rotation and translation from the reference frame is computed. Each raw frame is then digitally shifted, rotated, and slightly scaled (Electronic Image Stabilization, EIS) on the NPU to sub-pixel precision, perfectly registering it to the reference frame even if the user's hands moved by several full pixels of blur during the burst."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Temporal Pixel Merging"}),": For each pixel location across the 12 aligned frames, the algorithm gathers 12 candidate pixel values. It then performs robust statistical merging rather than a simple average: outlier values (caused by hot pixels, cosmic ray hits, or a car's headlights transiting that spot) are identified and discarded. The remaining consistent values are averaged, reducing Gaussian shot noise by a factor equal to the square root of the number of frames kept. A 12-frame merge reduces noise by 3.5\xd7."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Spatial Denoising"}),": A CNN-based denoiser (trained specifically on raw night imagery) removes any remaining high-frequency noise while preserving real edges and texture."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Local Tone Mapping"}),": The merged raw image has very high dynamic range. A spatially-varying tone mapping operator (based on bilateral filtering or a learned CNN tone map) lifts shadows without blowing out city lights, boosts color saturation in dark regions (which would otherwise look desaturated), and produces a final 8-bit image that feels bright and clean rather than dim and murky."]}),"\n"]}),"\n",(0,o.jsx)(t.mermaid,{value:"flowchart LR\n    A[Dark Scene: City Street at Night] --\x3e B[Capture 12 RAW Frames\\n1/15s each = 0.66s total]\n    B --\x3e C[Gyro EIS Alignment\\nSub-Pixel Shift + Rotate]\n    C --\x3e D[Temporal Merge\\nRobust Mean / Outlier Reject\\nNoise \u22123.5\xd7]\n    D --\x3e E[CNN Spatial Denoiser\\nPreserve Edges / Texture]\n    E --\x3e F[Local Tone Mapping\\nBoost Shadows / Preserve Lights]\n    F --\x3e G[Bright Clear Night Photo\\nLow Noise, No Blur]"}),"\n",(0,o.jsx)(t.p,{children:'Samsung\'s "Nightography," Apple\'s "Night Mode," Xiaomi\'s "Night Mode 2.0," and OPPO\'s "Ultra Dark Mode" all use substantially the same algorithm architecture. Variations exist in the exact number of frames, the choice of robust merging statistic, the denoiser architecture, and the tone map look, but the core gyro-aligned multi-frame temporal averaging is universal across the industry.'}),"\n",(0,o.jsx)(t.h2,{id:"slow-motion-high-frame-rate-cropped-capture",children:"Slow Motion: High-Frame-Rate Cropped Capture"}),"\n",(0,o.jsx)(t.p,{children:"Slow-motion video stretches time by capturing video frames faster than the standard 30 fps playback rate, then playing them back at the normal 30 fps speed. The common multipliers:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"120 fps capture \u2192 30 fps playback = 4\xd7 slow motion."})," A 1-second real-world event becomes 4 seconds of video."]}),"\n",(0,o.jsx)(t.li,{children:(0,o.jsx)(t.strong,{children:"240 fps \u2192 30 fps = 8\xd7 slow motion."})}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"960 fps \u2192 30 fps = 32\xd7 ultra-slow motion."})," A water drop splash, a balloon pop, or a hummingbird wingbeat becomes visible."]}),"\n"]}),"\n",(0,o.jsx)(t.h3,{id:"why-960-fps-requires-a-sensor-crop",children:"Why 960 fps Requires a Sensor Crop"}),"\n",(0,o.jsxs)(t.p,{children:["The bottleneck for high-frame-rate capture is ",(0,o.jsx)(t.strong,{children:"sensor readout bandwidth"}),". The image sensor has a finite number of MIPI CSI-2 lanes running at a fixed maximum data rate (typically 2.5 Gbps per lane, 4 lanes = 10 Gbps total). The sensor can only output so many pixels per second."]}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"A full 48MP (8000\xd76000) frame readout at 960 fps would require 48,000,000 \xd7 960 = 46.08 billion pixels per second. That is 30\xd7 the actual readout bandwidth of any 2026 smartphone sensor."}),"\n",(0,o.jsx)(t.li,{children:"Therefore, to hit 960 fps the sensor must read out only a small central crop of its pixel array. A 960 fps mode is typically a 1280\xd7720 (720p HD) or sometimes a 1920\xd71080 (1080p FHD) crop. The total pixel bandwidth becomes manageable: 1280\xd7720\xd7960 fps = 884 megapixels per second, which fits comfortably in 10 Gbps even with 10-bit per pixel encoding."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"The numbers in practice: 960 fps capture \xd7 0.3 seconds of real time = 288 individual frames. Played back at 30 fps = 9.6 seconds of buttery slow-motion video. Some Sony Xperia and Samsung Galaxy flagship phones support a brief burst of 960 fps at 1080p resolution by reading the sensor through a limited analog-to-digital converter (ADC) bank only in the central crop region."}),"\n",(0,o.jsx)(t.mermaid,{value:'flowchart TD\n    subgraph "Bandwidth Bottleneck: Sensor Readout"\n        direction TB\n        A[Full Sensor Mode:\\n48MP (8000\xd76000) @ 30fps\\n= 1.44 GPix/s\\n\u2192 Photo / Standard Video]\n        B[Slow-Motion Crop Mode:\\n1280\xd7720 @ 960fps\\n= 0.88 GPix/s\\n\u2192 32\xd7 Ultra Slow-Mo]\n    end\n    A --\x3e C{MIPI CSI-2 Bus\\n4 Lanes \xd7 2.5 Gbps\\n= 10 Gbps Total}\n    B --\x3e C\n    C --\x3e D[ISP Video Pipeline\\nScales to Output Resolution]\n    D --\x3e E[HEVC / AV1 Encoder\\nWrites Slow-Motion MP4]'}),"\n",(0,o.jsx)(t.p,{children:"Slow-motion modes also often use a staggered HDR technique where alternate rows of the sensor are exposed for different durations to maintain high dynamic range even at 240 fps or 960 fps."}),"\n",(0,o.jsx)(t.h2,{id:"ultra-wide-distortion-correction-and-edge-quality",children:"Ultra-Wide: Distortion Correction and Edge Quality"}),"\n",(0,o.jsx)(t.p,{children:'The ultra-wide camera on a modern flagship offers a 10\u201318mm full-frame equivalent focal length and a 100\xb0 to 130\xb0 diagonal field of view. It opens up compositional possibilities that the standard wide camera cannot: sweeping landscapes, towering architecture shots where the entire building fits without stepping into traffic, group selfies that actually include everyone, and a playful "close-up proximity distortion" effect where objects held near the lens appear massively oversized relative to the background.'}),"\n",(0,o.jsx)(t.p,{children:"However, the ultra-wide focal length comes with three characteristic optical flaws that the ISP must correct before the photo is usable:"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Geometric (Barrel) Distortion"}),": Straight lines bow outward like the edges of a fisheye lens. A photo of a rectangular door frame will look pincushioned or barreled. The ISP's Geometric Distortion Correction stage (see Chapter 2) applies a per-pixel coordinate remap using a 4th-order or 6th-order polynomial lens model calibrated for that specific module. The correction necessarily crops the outer 5\u201310% of the sensor array because the remapping pushes those outer pixels off-canvas."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Lateral Chromatic Aberration (LCA)"}),": The lens bends different wavelengths of light by slightly different amounts, so red, green, and blue images of the same off-axis point land at slightly different pixel coordinates. The result is visible color fringing (purple/green edges) on high-contrast objects near the corners. The ISP corrects LCA by applying a slightly different magnification factor to the red and blue color planes relative to green."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Vignetting / Corner Softness"}),": Corner pixels receive significantly less light than center pixels (due to the lens's cos\u2074\u03b8 natural falloff plus mechanical vignetting from the lens barrel), and the lens's optical MTF (Modulation Transfer Function) is lower at extreme angles so corners look soft. The Lens Shading Correction stage applies a radially symmetric gain boost to flatten the illumination, and an edge-aware sharpening filter is applied more aggressively at the corners than in the center."]}),"\n"]}),"\n",(0,o.jsx)(t.mermaid,{value:"flowchart LR\n    A[Raw Ultra-Wide Capture\\n120\xb0 Fisheye\\nBarrel Distorted] --\x3e B[ISP Geometric Correction\\n6th-Order Polynomial Remap]\n    B --\x3e C[Cropped Rectilinear Output\\nStraight Lines Actually Straight]\n    C --\x3e D[Lateral CA Correction\\nRed/Blue Plane Rescaling]\n    D --\x3e E[Lens Shading + Corner Sharpening]\n    E --\x3e F[Final Corrected Ultra-Wide Photo]"}),"\n",(0,o.jsx)(t.h2,{id:"telephoto-standard-vs-periscope",children:"Telephoto: Standard vs Periscope"}),"\n",(0,o.jsx)(t.p,{children:"The telephoto camera captures distant subjects that the wide camera cannot resolve. Modern phones ship two distinct telephoto designs."}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Standard Telephoto (2\xd7 to 3\xd7 optical):"})," This is a conventional camera module: the lens barrel sits perpendicular to the phone's back cover, directly above the image sensor, exactly like the wide camera but with a longer focal length lens. A 3\xd7 telephoto has an ~72mm full-frame equivalent focal length. The physical stack-up is limited by the phone's thickness (7\u20139mm), so the lens cannot be longer than that. Hence the 3\xd7 practical ceiling for conventional telephoto modules."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Periscope Telephoto (5\xd7 to 10\xd7 optical):"})," To get longer focal lengths without making the phone thicker, engineers folded the optical path 90\xb0 using a prism. Light enters through a window in the phone's edge or rear glass, hits a 45\xb0 right-angle prism, bounces 90\xb0 sideways, and then travels horizontally through a multi-element lens barrel 10\u201314mm long that runs parallel to the phone's mainboard, finally landing on an image sensor mounted sideways on the PCB. The prism itself is mounted on a 2-axis OIS gimbal, and the sensor is sometimes mounted on a separate sensor-shift OIS, giving 4-axis or 5-axis total stabilization \u2014 enough to get sharp handheld 10\xd7 photos of text on a distant building sign."]}),"\n",(0,o.jsx)(t.mermaid,{value:'graph LR\n    subgraph "Periscope Telephoto (Side View Inside Phone)"\n        direction LR\n        A[Light In\\nRear Glass Window] --\x3e B[45\xb0 Prism\\n90\xb0 Reflection]\n        B --\x3e C[Lens Element 1]\n        C --\x3e D[Lens Element 2]\n        D --\x3e E[Lens Element 3]\n        E --\x3e F[Lens Element 4]\n        F --\x3e G[Lens Element 5]\n        G --\x3e H[IR Cut Filter]\n        H --\x3e I[Image Sensor\\nMounted Horizontally]\n    end\n    J[Phone Thickness: 8.5mm Total] --\x3e B'}),"\n",(0,o.jsx)(t.p,{children:'At zoom boundaries between physical cameras (for example, 2.9\xd7 still digitally cropped from the wide camera vs 3.1\xd7 using the 3\xd7 periscope telephoto), the HAL performs a multi-camera fusion trick: for roughly \xb10.2\xd7 around the switchover point, it captures both cameras simultaneously and performs a cross-fade weighted by zoom ratio, so the user never sees a visible "jump" when the active physical camera changes.'}),"\n",(0,o.jsx)(t.h2,{id:"macro-extreme-close-up-photography",children:"Macro: Extreme Close-Up Photography"}),"\n",(0,o.jsx)(t.p,{children:"Macro photography captures extreme close-ups of small subjects: the texture of flower petals, the compound eyes of insects, the fibers of a piece of fabric, the individual sugar crystals on a cookie."}),"\n",(0,o.jsx)(t.p,{children:"Two macro strategies exist in modern phones:"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Dedicated Macro Camera:"})," Budget and mid-range phones often ship a small, low-resolution (2MP to 5MP) dedicated macro module with a fixed-focus short-focal-length lens. The module is tuned for a specific minimum focus distance (typically 2\u20134 cm) and produces surprisingly sharp macro images despite its low resolution. The main drawback is that the sensor is tiny, so image quality degrades sharply in anything less than bright daylight."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ultra-Wide Re-purposed as Macro:"}),' Flagship phones (Google Pixel, Samsung S-series Ultra, iPhone Pro) do not ship a dedicated macro camera. Instead, they re-task the ultra-wide camera. The ultra-wide\'s short focal length (13mm eq) gives it a very short minimum focus distance \u2014 often 1 to 2 centimeters from the subject. When the user taps "Macro" mode or the camera app detects a close subject via the ToF sensor or phase-detect AF rangefinder, the app switches to the ultra-wide, drives its VCM to the minimum-focus position, applies extra geometric distortion correction (because the subject is now at a field-curvature extreme where the polynomial remap differs significantly from the infinity calibration), and crops the center of the ultra-wide sensor to produce the final macro frame. The large 12MP\u201350MP ultra-wide sensor gives dramatically better macro image quality than a 5MP dedicated module.']}),"\n",(0,o.jsx)(t.h2,{id:"computational-photography-the-unifying-philosophy",children:"Computational Photography: The Unifying Philosophy"}),"\n",(0,o.jsxs)(t.p,{children:["The features above \u2014 HDR, Portrait, Night Mode, Slow Motion, Ultra-Wide correction, Periscope zoom fusion, Macro \u2014 share a single unifying idea. ",(0,o.jsx)(t.strong,{children:"Computational photography"})," is the philosophy that the camera sensor, the ISP, the gyroscope/IMU, the NPU (Neural Processing Unit), and multi-frame signal processing algorithms can work together to produce imagery that no single lens/sensor combination, no matter how expensive the glass, could ever produce on its own."]}),"\n",(0,o.jsx)(t.p,{children:"The classic DSLR model is: light \u2192 lens \u2192 sensor \u2192 storage. The smartphone model is: light \u2192 multiple lenses \u2192 multiple sensors \u2192 gyro/IMU \u2192 multi-frame burst capture \u2192 NPU neural inference \u2192 per-pixel decision fusion \u2192 sophisticated tone mapping \u2192 storage. Both start and end at the same place, but the smartphone inserts dozens of additional computational steps in the middle, each of which improves the final result in ways optics alone cannot."}),"\n",(0,o.jsx)(t.p,{children:"Zooming seamlessly across 0.5\xd7 to 10\xd7 on a Galaxy S26 Ultra is computational: the HAL blends three different cameras with three different focal lengths across five zoom switch points. Rescuing a backlit portrait where the window behind the subject no longer blows out is computational: 7-frame HDR fusion. A handheld night photo of the Milky Way that would require a tripod and a 30-second exposure on a DSLR is computational: 12-frame gyro-aligned temporal merge. Every feature described in this chapter is computational photography."}),"\n",(0,o.jsx)(t.mermaid,{value:'graph TD\n    subgraph "Computational Photography Venn Diagram"\n        A[Optics\\nLenses, Aperture, OIS]\n        B[Sensors\\nCMOS, Bayer, Rolling Shutter]\n        C[Machine Learning\\nSegmentation, Denoise, Depth]\n        D[Multi-Frame Signal Processing\\nHDR Merge, Night Merge, EIS]\n    end\n    A -- Overlap --\x3e E[Portrait Bokeh]\n    B -- Overlap --\x3e F[HDR Bracketed Capture]\n    C -- Overlap --\x3e G[ML Portrait Segmentation]\n    D -- Overlap --\x3e H[Night Sight Temporal Merge]\n    A & B & C & D --\x3e I[Seamless Multi-Camera Zoom]'}),"\n",(0,o.jsx)(t.p,{children:'This is the most important idea to carry into the Camera2 API chapters that follow. The Camera2 API is not just a tool to "take a picture." It is a low-level control interface that lets your app fire precise multi-frame bursts, read gyro metadata per frame, select which physical camera fires at which zoom ratio, and stream frames through on-device neural networks \u2014 the building blocks for implementing your own computational photography features.'}),"\n",(0,o.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsx)(t.p,{children:"In this chapter you learned the real-world algorithms behind modern smartphone photography features. HDR uses 3\u201310 frame exposure bracketing, per-frame feature-based alignment, and tone mapping to capture dynamic range the sensor cannot see in a single exposure. Portrait mode computes a per-pixel depth map via stereo camera disparity, ToF laser ranging, or monocular ML depth estimation, then runs a U-Net subject segmentation and applies a variable per-pixel Gaussian blur scaled by depth. Night mode captures 8\u201315 short exposures, aligns them using gyro-aided EIS, applies robust temporal pixel merging to reduce noise by 3.5\xd7, and locally tone-maps the result. Slow-motion video at 960 fps must crop the sensor because the MIPI readout bandwidth is the hard bottleneck. Ultra-wide photos undergo geometric distortion correction, chromatic aberration correction, and corner shading correction in the ISP before they become viewable. Periscope telephoto cameras use a 45\xb0 prism to fold the light path 90\xb0 and fit a 10\xd7 optical lens inside an 8.5mm-thick phone. You learned the definition of computational photography: the fusion of Optics, Sensors, Machine Learning, and Multi-Frame Signal Processing to create images beyond the reach of any single lens/sensor system."}),"\n",(0,o.jsx)(t.h2,{id:"whats-next",children:"What's Next"}),"\n",(0,o.jsxs)(t.p,{children:["Chapter 4 is the hands-on practical chapter. You will install the ",(0,o.jsx)(t.strong,{children:"Android Camera Parameters"})," companion app from source or Google Play, launch it on your own phone, and inspect exactly what your own hardware is capable of. You will learn to read Camera IDs and facing directions, check the Hardware Level of each camera (LEGACY / LIMITED / FULL / LEVEL_3), enumerate supported output formats (JPEG, YUV_420_888, PRIVATE, RAW_SENSOR, JPEG_R Ultra HDR), find maximum slow-motion FPS ranges, explore zoom ratios and switch points between your phone's physical cameras, and check whether your primary sensor supports RAW capture \u2014 writing down the answers for your specific device, because those answers determine what is and is not possible for your own Camera2 API app to do on that phone."]})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>s});var r=a(6540);const o={},n=r.createContext(o);function i(e){const t=r.useContext(n);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),r.createElement(n.Provider,{value:t},e.children)}}}]);